+   A vertical rail runs down the left; month headers sit on it as filled dots
+   and each entry hangs off it as an emoji chip. The rail is a single
+   pseudo-element on the list so it stays continuous across hidden rows. */
+/* The timeline sits inside a full-width card; give it a little more room than
+   the default card padding on wide screens. */
+@media (min-width: 768px) {
+  .lf-tl-card {
+    padding: 2rem 2.5rem;
+  }
 }

-.lf-newsbar-row {
-  display: flex;
-  align-items: center;
-  gap: 1rem;
-  min-height: 3.75rem;
-  font-size: .9375rem;
+.lf-tl {
+  --tl-x: 1.25rem;
+  /* rail centre, measured from the list's left edge */
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  position: relative;
 }

-.lf-newsbar-tag {
-  flex: none;
+.lf-tl::before {
+  content: "";
+  position: absolute;
+  left: calc(var(--tl-x) - 1px);
+  top: .75rem;
+  bottom: .75rem;
+  width: 2px;
+  border-radius: 2px;
+  background: linear-gradient(180deg, #6366F1 0%, #C7D2FE 70%, rgba(199, 210, 254, 0) 100%);
+}
+
+.lf-tl [hidden] {
+  display: none;
+}
+
+.lf-tl-month {
+  position: relative;
+  padding: 1.5rem 0 .5rem calc(var(--tl-x) + 1.75rem);
+  font-size: .8125rem;
   font-weight: 700;
+  letter-spacing: .04em;
   color: #4338CA;
 }

-/* min-width:0 is what lets the title actually shrink and ellipsize inside a
-   flex row — without it the flex item refuses to go below its content width. */
-.lf-newsbar-link {
-  display: flex;
-  align-items: baseline;
-  gap: .5rem;
-  min-width: 0;
-  flex: 1 1 auto;
-  color: #1f2937;
-  text-decoration: none;
+.lf-tl-month:first-child {
+  padding-top: 0;
 }

-.lf-newsbar-title {
-  min-width: 0;
-  overflow: hidden;
-  white-space: nowrap;
-  text-overflow: ellipsis;
-  font-weight: 600;
+/* Filled dot with a halo, centred on the rail. */
+.lf-tl-month::before {
+  content: "";
+  position: absolute;
+  left: calc(var(--tl-x) - .4375rem);
+  top: calc(1.5rem + .2rem);
+  width: .875rem;
+  height: .875rem;
+  border-radius: 50%;
+  background: #4F46E5;
+  box-shadow: 0 0 0 4px #fff, 0 0 0 5px #C7D2FE;
 }

-.lf-newsbar-link:hover .lf-newsbar-title {
-  color: #4F46E5;
-  text-decoration: underline;
+.lf-tl-month:first-child::before {
+  top: .2rem;
 }

-.lf-newsbar-date {
-  flex: none;
-  color: #6b7280;
-  font-variant-numeric: tabular-nums;
+.lf-tl-item {
+  position: relative;
+  display: flex;
+  align-items: flex-start;
+  gap: .875rem;
+  padding: .5rem 0;
+}
+
+.lf-tl-item {
+  padding-left: calc(var(--tl-x) - 1.05rem);
 }

-.lf-newsbar-all {
+/* Emoji chip sits on the rail; the white ring masks the line behind it. */
+.lf-tl-ico {
   flex: none;
+  display: grid;
+  place-items: center;
+  width: 2.1rem;
+  height: 2.1rem;
+  border-radius: 50%;
+  background: #EEF2FF;
+  border: 1px solid #C7D2FE;
+  box-shadow: 0 0 0 3px #fff;
+  font-size: 1rem;
+  line-height: 1;
+}
+
+.lf-tl-text {
+  margin: 0;
+  min-width: 0;
+  padding-top: .3rem;
+  font-size: .95rem;
+  line-height: 1.6;
+  color: #374151;
+  overflow-wrap: anywhere;
+}
+
+.lf-tl-text b {
+  color: #111827;
+  font-weight: 650;
+}
+
+.lf-tl-link {
+  margin-left: .25rem;
+  white-space: nowrap;
   font-weight: 600;
   color: #4F46E5;
   text-decoration: none;
 }

-.lf-newsbar-all:hover {
+.lf-tl-link:hover {
