-.dark .lf-newsbar-tag {
+.lf-tl-more:hover {
+  background: #EEF2FF;
+  border-color: #A5B4FC;
+}
+
+.lf-tl-more[hidden] {
+  display: none;
+}
+
+.lf-tl-more:focus-visible,
+.lf-tl-link:focus-visible {
+  outline: 2px solid #6366F1;
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+.dark .lf-tl::before {
+  background: linear-gradient(180deg, #818CF8 0%, rgba(99, 102, 241, .35) 70%, rgba(99, 102, 241, 0) 100%);
+}
+
+.dark .lf-tl-month {
   color: #A5B4FC;
 }

-.dark .lf-newsbar-link {
-  color: #e5e7eb;
