+  }
+
+  .lf-tl-month {
+    padding-left: calc(var(--tl-x) + 1.5rem);
+  }
+
+  .lf-tl-item {
+    gap: .625rem;
+  }

-  .lf-newsbar-date,
-  .lf-newsbar-all {
-    display: none;
+  .lf-tl-text {
+    font-size: .9rem;
   }
 }

